<body>
<main class="app">
  <header>
    <h1>Todos</h1>
    <p>Stay organized. Everything is saved locally.</p>
  </header>

  <form id="todo-form" class="input-row" autocomplete="off">
    <input id="todo-input" type="text" placeholder="What needs to be done?" maxlength="300" aria-label="New todo">
    <button id="add-btn" type="submit">Add</button>
  </form>

  <div class="filters" role="group" aria-label="Filter todos">
    <button class="filter-btn active" data-filter="all">All</button>
    <button class="filter-btn" data-filter="active">Active</button>
    <button class="filter-btn" data-filter="completed">Completed</button>
  </div>

  <ul id="todo-list" aria-live="polite"></ul>
  <div id="empty-state" class="empty-state" hidden>No todos here.</div>

  <footer>
    <span id="counter">0 items left</span>
    <button id="clear-completed" type="button" hidden>Clear completed</button>
  </footer>
</main>

<script>
(function () {
  'use strict';

  var STORAGE_KEY = 'todos.ollama-qwen3.8-flash-next-125b-a6b-q4_01';

  var todos = load();
  var currentFilter = 'all';

  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var list = document.getElementById('todo-list');
  var emptyState = document.getElementById('empty-state');
  var counter = document.getElementById('counter');
  var clearBtn = document.getElementById('clear-completed');
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed.filter(function (t) {
        return t && typeof t.id === 'string' && typeof t.text === 'string';
      }) : [];
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) { /* storage unavailable — app still works in-memory */ }
  }

  function addTodo(text) {
    todos.push({
      id: Date.now().toString(36) + Math.random().toString(36).slice(2, 8),
      text: text,
      completed: false
    });
    save();
    render();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    save();
    render();
  }

  function deleteTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function visibleTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  function render() {
    list.innerHTML = '';
    var items = visibleTodos();

    items.forEach(function (todo) {
      var li = document.createElement('li');
      li.className = 'todo-item' + (todo.completed ? ' completed' : '');

      var checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.className = 'todo-checkbox';
      checkbox.checked = todo.completed;
      checkbox.setAttribute('aria-label', todo.completed ? 'Mark as active' : 'Mark as complete');
      checkbox.addEventListener('change', function () { toggleTodo(todo.id); });

      var span = document.createElement('span');
      span.className = 'todo-text';
      span.textContent = todo.text;
      span.addEventListener('click', function () { toggleTodo(todo.id); });

      var del = document.createElement('button');
      del.className = 'delete-btn';
      del.type = 'button';
      del.textContent = '\u00d7';
      del.setAttribute('aria-label', 'Delete todo');
      del.addEventListener('click', function () { deleteTodo(todo.id); });

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });

    var emptyMessages = {
      all: 'No todos yet. Add one above!',
      active: 'Nothing active — nice work!',
      completed: 'No completed todos yet.'
    };
    emptyState.textContent = emptyMessages[currentFilter];
    emptyState.hidden = items.length > 0;

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    counter.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearBtn.hidden = !hasCompleted;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    addTodo(text);
    input.value = '';
    input.focus();
  });

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      currentFilter = btn.getAttribute('data-filter');
      filterBtns.forEach(function (b) { b.classList.toggle('active', b === btn); });
      render();
    });
  });

  clearBtn.addEventListener('click', clearCompleted);

  render();
})();
</script>
</body>
</html>
